/** The languages offered, each named in itself, in the order the selector lists them. */
const LANGUAGES = [
  ["en", "English"], ["ko", "한국어"], ["zh", "简体中文"], ["ja", "日本語"], ["es", "Español"], ["pt", "Português (BR)"],
];

/** A BCP 47 tag ("zh-Hans-CN", "pt-PT", "ko") as one of ours, or null. Every Chinese locale gets the
 * Simplified text and every Portuguese one the Brazilian text: closer than English for each. */
function langOf(tag) {
  const base = String(tag || "").toLowerCase().split(/[-_]/)[0];
  return LANGUAGES.some(([code]) => code === base) ? base : null;
}

// A language the user picked in the selector wins; then ?lang= (the tray app passes the OS
// language there, because navigator.language is Chromium's app locale and read "en" on a Korean
// Windows); then the browser's own language.
function detectLang() {
  try {
    const stored = langOf(localStorage.getItem("clauderipple_lang"));
    if (stored) return stored;
  } catch { /* storage unavailable */ }
  try {
    const q = langOf(new URLSearchParams(location.search).get("lang"));
    if (q) return q;
  } catch { /* no location */ }
  return langOf(navigator.language) || "en";
}
const CURRENT_LANG = detectLang();
function t(key, vars) {
  const dictionary = I18N[CURRENT_LANG] || I18N.en;
  let text = dictionary[key] !== undefined ? dictionary[key] : (I18N.en[key] !== undefined ? I18N.en[key] : key);
  for (const [name, value] of Object.entries(vars || {})) text = text.split(`{${name}}`).join(String(value));
  return text;
}
function applyStaticI18n() {
  for (const node of document.querySelectorAll("[data-i18n]")) node.textContent = t(node.getAttribute("data-i18n"));
  for (const node of document.querySelectorAll("[data-i18n-placeholder]")) node.setAttribute("placeholder", t(node.getAttribute("data-i18n-placeholder")));
  for (const node of document.querySelectorAll("[data-i18n-title]")) {
    const text = t(node.getAttribute("data-i18n-title"));
    node.setAttribute("title", text);
    node.setAttribute("aria-label", text);
  }
  document.title = t("brand");
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", applyStaticI18n); else applyStaticI18n();
